    'Blood & iron': { bg: '#140E0E', panel: '#241818', text: '#EAD9D4', accent: '#D2665A' },
    'Elven grove':  { bg: '#0F1610', panel: '#19251B', text: '#E1EAD9', accent: '#9BC07F' },
