        return '<div class="tbl-row"><div class="main"><b>' + esc(factionName(camp.id, n.fid)) + (n.major ? ' <span class="tag">Major</span>' : '') + '</b><span>' + esc(n.text) + (n.at ? ' · ' + esc(n.at) : '') + ' · day ' + n.day + '</span></div></div>';
