    var m = src ? JSON.parse(JSON.stringify(src)) : { size: 'Medium', type: 'Humanoid', align: 'Neutral', ac: '12', hp: '11 (2d8 + 2)', speed: '30 ft.', cr: '1/2', abil: {}, secs: {} };
