    var secText = function (sec) { var v = (m.secs || {})[sec]; var list = Array.isArray(v) ? v : v ? v.list || [] : []; return list.map(function (x) { return x[0] + ' | ' + String(x[1]).replace(/«|»/g, '').replace(/\n/g, ' '); }).join('\n'); };
