      if (tl.how === 'paid') { var who = tl.payer ? charName(tl.payer) : ''; return ' Paid ' + money(tl.cp) + ' toll at ' + tl.label + (who ? ' (' + who + ' paid)' : '') + '.'; }
      return tl.how === 'talked' ? ' Talked their way past the toll at ' + tl.label + '.' : ' Went around the toll at ' + tl.label + '.';
