    if (st.speed) bits.push((st.speed > 0 ? '+' : '') + Math.round(st.speed * 100) + '% speed');
    if (st.profit) bits.push((st.profit > 0 ? '+' : '') + Math.round(st.profit * 100) + '% profit');
