    if (rows.length) html += '<div class="tbl" style="margin-bottom:6px">' + rows.join('') + '</div>' + (dm ? '<label class="note"><input type="checkbox" id="hfitpay-' + esc(h.id) + '" checked> Pay for fittings from the coffer</label>' : '');
    return html;
