          var tgtW = standing.filter(function (x) { return x.n !== 'Tower'; })[0] || standing[0]; if (!tgtW) return;
          var avg = Math.round(en2.dice * 5.5); if (avg >= tgtW.dt) tgtW.hp = Math.max(0, tgtW.hp - avg);
