      s[path[0]][path[1]] = path[1] === 'regen' ? t.value : Math.max(0, num(t.value, 0));
      if (path[1] === 'max') s[path[0]].cur = Math.min(num(s[path[0]].cur, 0), num(s[path[0]].max, 0));
